/**
 * 직원 목록 조회 쿼리를 짓는 규칙.
 *
 * 화면의 필터(검색어·재직상태·배정상태·조직)는 여러 자리에서 조회를 부른다 —
 * 첫 로드, 검색 제출, Select 세 개, 가져오기 뒤 새로고침. 그 자리마다
 * `new URLSearchParams` 을 손으로 조립하면 한쪽만 키 이름을 틀리거나 빈 값을
 * `?status=` 로 흘려 서버가 다르게 읽는다 — 이 저장소에서 반복된 어긋남이다.
 * 그래서 키 이름과 빈 값 규칙을 여기 한 곳에 두고 부르는 쪽이 모두 이것을 쓴다.
 * `seatMapLink.ts`·`silentSso.ts`·`employeeExport.ts` 가 같은 꼴의 짝이다.
 *
 * 키 이름은 마음대로 짓지 않는다. 서버 `listEmployees`
 * (`internal/app/employees.go:59-63`)가 읽는 `q`·`organizationId`·`status`·
 * `assignment` 를 그대로 쓴다.
 */

/**
 * 한 번에 받아 오는 최대 인원.
 *
 * 서버는 `limit` 을 500 까지만 받고(`employees.go:65-67`) 전체 건수는 돌려주지
 * 않는다. 그래서 화면은 언제나 상한으로 받고 "최대 500명 표시" 를 안내한다 —
 * 조건에 상관없이 같은 값이어야 표에 보이는 것과 CSV 가 어긋나지 않는다.
 */
export const EMPLOYEE_QUERY_LIMIT = "500";

export interface EmployeeFilters {
  /** 이름·사번·이메일·조직명을 함께 훑는 자유 검색어. */
  q?: string;
  /** 재직상태 코드(active|leave|retired). 빈 값은 전체. */
  status?: string;
  /** 배정상태(assigned|unassigned). 빈 값은 전체. */
  assignment?: string;
  /** 조직 id. 빈 값은 전체 조직. 조직명이 아니라 id 다. */
  organizationId?: string;
}

/**
 * 주어진 필터로 `GET /api/v1/employees` 의 쿼리를 짓는다.
 *
 * 빈 값(공백만 있는 것도 포함)은 키를 아예 넣지 않는다. 서버는 `$1=''` 로 빈
 * 값을 전체로 치므로 넣어도 결과는 같지만, 키가 없으면 주소가 짧아 어떤 조건이
 * 걸려 있는지 눈으로 읽힌다.
 */
export function employeeQuery(filters: EmployeeFilters): URLSearchParams {
  const params = new URLSearchParams({ limit: EMPLOYEE_QUERY_LIMIT });
  const put = (key: string, value: string | undefined) => {
    const trimmed = value?.trim();
    if (trimmed) params.set(key, trimmed);
  };
  put("q", filters.q);
  put("organizationId", filters.organizationId);
  put("status", filters.status);
  put("assignment", filters.assignment);
  return params;
}
import { describe, expect, it } from "vitest";
import { EMPLOYEE_QUERY_LIMIT, employeeQuery } from "./employeeQuery";

const query = (next: Parameters<typeof employeeQuery>[0] = {}): string =>
  employeeQuery(next).toString();

describe("employeeQuery", () => {
  it("아무 조건도 없으면 limit 만 붙는다", () => {
    expect(query()).toBe("limit=500");
  });

  it("빈 문자열은 키를 아예 넣지 않는다", () => {
    expect(
      query({ q: "", status: "", assignment: "", organizationId: "" }),
    ).toBe("limit=500");
  });

  it("공백만 있는 값도 없는 것과 같다", () => {
    expect(query({ q: "   ", organizationId: "  " })).toBe("limit=500");
  });

  it("조직을 고르면 organizationId 키로 실린다", () => {
    expect(query({ organizationId: "org-1" })).toBe(
      "limit=500&organizationId=org-1",
    );
  });

  it("네 조건이 모두 있으면 모두 실린다", () => {
    const params = employeeQuery({
      q: "김개발",
      status: "active",
      assignment: "assigned",
      organizationId: "org-1",
    });
    expect(params.get("q")).toBe("김개발");
    expect(params.get("status")).toBe("active");
    expect(params.get("assignment")).toBe("assigned");
    expect(params.get("organizationId")).toBe("org-1");
    expect(params.get("limit")).toBe("500");
  });

  it("검색어의 공백은 떼고 싣는다", () => {
    expect(employeeQuery({ q: "  김개발  " }).get("q")).toBe("김개발");
  });

  it("limit 은 조건과 무관하게 언제나 500 이다", () => {
    expect(employeeQuery({}).get("limit")).toBe("500");
    expect(employeeQuery({ organizationId: "org-1" }).get("limit")).toBe("500");
    expect(EMPLOYEE_QUERY_LIMIT).toBe("500");
  });

  it("호출자가 준 값을 담은 새 객체를 돌려준다 — 부르는 쪽끼리 섞이지 않는다", () => {
    const first = employeeQuery({ organizationId: "org-1" });
    const second = employeeQuery({});
    expect(first.get("organizationId")).toBe("org-1");
    expect(second.get("organizationId")).toBeNull();
  });
});
import { expect, test } from "@playwright/test";
import { readFileSync } from "node:fs";
import { login } from "./helpers";

/**
 * 직원 화면의 조직 필터.
 *
 * 서버 `listEmployees` 는 `organizationId` 를 이미 걸러 주지만(employees.go:62,69)
 * 화면에 그것을 고를 자리가 없었다. 여기서 보는 것은 화면의 Select 가 정말 그
 * 쿼리를 실어 보내는지(표가 그 조직만 남는지)와, 걸러진 목록이 그대로 CSV 로
 * 내려오는지다. 쿼리 조립 규칙 자체는 vitest(`src/lib/employeeQuery.test.ts`)가
 * 증명한다.
 *
 * 이 검증은 서버 상태를 바꾸지 않는다 — 화면의 필터만 만지므로 되돌릴 것이 없다.
 * 시드는 조직 3개와 직원 10명(개발팀 6·영업팀 2·인사팀 2)을 만든다(seed.mjs).
 */

/** 표의 '조직' 칸. 머리글 순서는 직원·사번·조직·직책/직급·좌석·상태·작업. */
const ORG_COLUMN = 2;

const chooseOrganization = async (
  page: import("@playwright/test").Page,
  name: string,
) => {
  await page.getByRole("combobox", { name: "조직 필터" }).click();
  await page.getByRole("option", { name, exact: true }).click();
};

test.describe("직원 조직 필터", () => {
  test.beforeEach(async ({ page }) => login(page));

  test("조직을 고르면 그 조직의 직원만 표에 남는다", async ({ page }) => {
    await page.goto("/admin/employees");
    const rows = page.locator("table tbody tr");
    // 거르기 전에는 시드 직원 10명이 모두 보인다.
    await expect(rows).toHaveCount(10);

    await chooseOrganization(page, "영업팀");

    await expect(rows).toHaveCount(2);
    const orgs = await rows
      .locator(`td:nth-child(${ORG_COLUMN + 1})`)
      .allTextContents();
    expect(orgs).toEqual(["영업팀", "영업팀"]);
  });

  test("조직 필터는 검색어를 지우지 않는다", async ({ page }) => {
    await page.goto("/admin/employees");
    const search = page.getByPlaceholder("이름, 사번, 이메일, 조직 검색");
    // 개발팀에만 있는 이름. 영업팀으로 거르면 두 조건이 겹쳐 아무도 남지 않는다.
    await search.fill("김개발");
    // exact 가 없으면 AppShell 의 "직원 빠른 검색" 단추까지 잡혀 strict 위반이 된다.
    await page.getByRole("button", { name: "검색", exact: true }).click();
    await expect(page.locator("table tbody tr")).toHaveCount(1);

    await chooseOrganization(page, "영업팀");

    await expect(search).toHaveValue("김개발");
    await expect(page.getByText("조건에 맞는 직원이 없습니다.")).toBeVisible();
    await expect(
      page.getByRole("button", { name: "CSV 내보내기" }),
    ).toBeDisabled();
  });

  test("걸러진 목록만 CSV 로 내려온다", async ({ page }) => {
    await page.goto("/admin/employees");
    await chooseOrganization(page, "영업팀");
    await expect(page.locator("table tbody tr")).toHaveCount(2);

    const button = page.getByRole("button", { name: "CSV 내보내기" });
    await expect(button).toBeEnabled();
    // 내려받기는 클릭과 거의 동시에 일어나므로 기다림을 클릭 전에 걸어야 한다.
    const wait = page.waitForEvent("download");
    await button.click();
    const download = await wait;

    const text = readFileSync((await download.path())!, "utf8");
    const lines = text.split("\r\n");
    // 머리글 한 줄 + 영업팀 2명. 거르기 전 10명이 담기면 안 된다.
    expect(lines.length - 1).toBe(2);
    expect(text).not.toContain("개발팀");
    expect(text).toContain("영업팀");
  });
});
