    -o /out/seaton ./cmd/seaton

FROM debian:bookworm-slim
LABEL org.opencontainers.image.title="SeatOn" \
      org.opencontainers.image.description="Offline-ready smart office seat management" \
      org.opencontainers.image.source="https://github.com/hkjang/seaton"
RUN apt-get update && apt-get install -y --no-install-recommends ca-certificates tzdata poppler-utils \
    && rm -rf /var/lib/apt/lists/* \
    && groupadd --system --gid 10001 seaton \
    && useradd --system --uid 10001 --gid seaton --home-dir /var/lib/seaton seaton \
    && install -d -o seaton -g seaton -m 0700 /var/lib/seaton
COPY --from=backend --chown=seaton:seaton /out/seaton /usr/local/bin/seaton
USER 10001:10001
EXPOSE 8080
VOLUME ["/var/lib/seaton"]
ENTRYPOINT ["/usr/local/bin/seaton"]
/**
 * 화면 검증용 시드 데이터.
 *
 * 빈 데이터베이스에 사업장·층·도면·좌석·직원·배정을 넣어, 좌석맵과 변경 이력이
 * 실제 운영과 비슷한 모습으로 그려지게 한다. 이미 도면이 있으면 아무것도 하지
 * 않으므로 여러 번 실행해도 안전하다.
 */
import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

/** 검증이 기준으로 삼는 도면 버전. */
const BASE_VERSION = "v1";

const ORGS = [
  { externalId: "DEV", name: "개발팀", color: "#3478C8" },
  { externalId: "SALES", name: "영업팀", color: "#E7692F" },
  { externalId: "HR", name: "인사팀", color: "#7B5EA7" },
];
const PEOPLE = [
  ["김개발", "개발팀"],
  ["이코딩", "개발팀"],
  ["박서버", "개발팀"],
  ["최프론트", "개발팀"],
  ["정영업", "영업팀"],
  ["한세일즈", "영업팀"],
  ["오인사", "인사팀"],
  ["윤총무", "인사팀"],
  ["서기획", "개발팀"],
  ["남디자", "개발팀"],
];

/** 세션 쿠키와 CSRF 토큰을 들고 다니는 최소 클라이언트. */
const client = async (baseURL, username, password) => {
  let cookie = "";
  let csrf = "";
  const call = async (method, path, { json, form } = {}) => {
    const headers = { ...(cookie && { Cookie: cookie }) };
    if (csrf) headers["X-CSRF-Token"] = csrf;
    if (json) headers["Content-Type"] = "application/json";
    const res = await fetch(baseURL + path, {
      method,
      headers,
      body: form ?? (json ? JSON.stringify(json) : undefined),
    });
    const set = res.headers.getSetCookie?.() ?? [];
    if (set.length) cookie = set.map((c) => c.split(";")[0]).join("; ");
    if (!res.ok) {
      throw new Error(`${method} ${path} → ${res.status} ${await res.text()}`);
    }
    return res.status === 204 ? {} : res.json();
  };
  await call("POST", "/api/v1/auth/login", { json: { username, password } });
  csrf = (await call("GET", "/api/v1/auth/me")).csrfToken;
  return call;
};

const settle = async (call, jobId) => {
  for (let i = 0; i < 90; i++) {
    const job = await call("GET", `/api/v1/analysis-jobs/${jobId}`);
    if (job.status === "completed") return job;
    if (job.status === "failed") throw new Error(`분석 실패: ${job.error}`);
    await new Promise((r) => setTimeout(r, 1000));
  }
  throw new Error("분석이 끝나지 않았습니다");
};

/**
 * 이미 시드가 있는 환경을 검증 시작 상태로 되돌린다.
 *
 * 도면 게시를 바꾸는 검증이 도중에 끊기면 게시된 도면이 하나도 없는 채로 남고,
 * 그 뒤 모든 검증이 "좌석맵에 아무것도 없다"는 이유로 무너진다. 실행마다 기준
 * 버전을 다시 게시하고 남은 확인용 버전을 치운다.
 */
const repair = async (call, maps) => {
  const base = maps.find((map) => map.version === BASE_VERSION);
  if (!base) return { seeded: false, repaired: false };
  let repaired = false;
  for (const map of maps) {
    if (map.version === BASE_VERSION || !map.id) continue;
    try {
      if (map.active)
        await call("POST", `/api/v1/floor-maps/${map.id}/unpublish`);
      await call("DELETE", `/api/v1/floor-maps/${map.id}`);
      repaired = true;
    } catch {
      // 배정이나 이력이 걸린 버전은 그대로 둔다.
    }
  }
  if (!base.active) {
    await call("POST", `/api/v1/floor-maps/${base.id}/publish`);
    repaired = true;
  }
  return { seeded: false, repaired };
};

export const seed = async ({ baseURL, username, password }) => {
  const call = await client(baseURL, username, password);
  const existing = await call("GET", "/api/v1/floor-maps");
  if (existing.items?.length) return repair(call, existing.items);

  const building = await call("POST", "/api/v1/buildings", {
    json: { name: "본사", code: "HQ" },
  });
  const floor = await call("POST", "/api/v1/floors", {
    json: { buildingId: building.id, name: "3층", code: "3F" },
  });

  const form = new FormData();
  form.set("floorId", floor.id);
  form.set("version", BASE_VERSION);
  const plan = await readFile(
    fileURLToPath(new URL("./fixtures/plan.png", import.meta.url)),
  );
  form.set("file", new Blob([plan], { type: "image/png" }), "plan.png");
  await call("POST", "/api/v1/floor-maps", { form });

  const maps = await call("GET", `/api/v1/floor-maps?floorId=${floor.id}`);
  const mapId = maps.items[0].id;
  const job = await call(
    "POST",
    `/api/v1/floor-maps/${mapId}/analyze?engine=cv`,
  );
  await settle(call, job.jobId);
  await call("POST", `/api/v1/floor-maps/${mapId}/publish`);
  const seats = (await call("GET", `/api/v1/seats?floorMapId=${mapId}`)).items;
  if (seats.length < PEOPLE.length) {
    throw new Error(`좌석이 ${seats.length}개만 인식되었습니다`);
  }

  for (const org of ORGS)
    await call("POST", "/api/v1/organizations", { json: org });
  const orgs = Object.fromEntries(
    (await call("GET", "/api/v1/organizations")).items.map((o) => [
      o.name,
      o.id,
    ]),
  );

  for (const [i, [name, team]] of PEOPLE.entries()) {
    await call("POST", "/api/v1/employees", {
      json: {
        employeeNo: `E${String(i + 1).padStart(3, "0")}`,
        name,
        organizationId: orgs[team],
        title: "팀원",
        status: "active",
      },
    });
  }
  const employees = (await call("GET", "/api/v1/employees?limit=50")).items;
  const byName = Object.fromEntries(employees.map((e) => [e.name, e]));
  for (const [i, [name]] of PEOPLE.entries()) {
    await call("POST", "/api/v1/seat-assignments", {
      json: {
        employeeId: byName[name].id,
        seatId: seats[i].id,
        source: "manual",
        reason: "초기 배치",
      },
    });
  }
  // 앞줄 좌석에 개발팀 구역을 지정한다. 영업팀 직원이 앉은 자리가 하나 섞여
  // 있어 "구역 불일치" 표시도 함께 검증된다.
  for (const seat of seats.slice(0, 5)) {
    await call("PATCH", `/api/v1/seats/${seat.id}`, {
      json: { organizationId: orgs["개발팀"] },
    });
  }
  return { seeded: true, mapId, seats: seats.length };
};

if (import.meta.url === `file://${process.argv[1]}`) {
  console.log(
    await seed({
      baseURL: process.env.E2E_BASE_URL ?? "http://127.0.0.1:18781",
      username: process.env.E2E_USERNAME ?? "admin",
      password: process.env.E2E_PASSWORD ?? "e2e-verify-pass-123",
    }),
  );
}
import { expect, test, type Page } from "@playwright/test";
import { submitLoginForm } from "./helpers";

test.describe("로그인 화면", () => {
  test("서버에 닿지 못하면 설정 문제로 안내하지 않고 다시 시도를 준다", async ({
    page,
  }) => {
    // 연결 실패를 "로그인 방식이 없다"로 안내하면, 관리자는 고칠 수 없는 설정
    // 화면을 들여다보게 되고 로그인 입력란까지 사라진다.
    await page.route("**/api/v1/**", (route) => route.abort("failed"));
    await page.goto("/login");
    await expect(page.getByText(/서버에 연결하지 못했습니다/)).toBeVisible();
    await expect(
      page.getByText(/사용 가능한 로그인 방식이 없습니다/),
    ).toHaveCount(0);

    await page.unroute("**/api/v1/**");
    await page.getByRole("button", { name: "다시 시도" }).click();
    await expect(page.locator('input[autocomplete="username"]')).toBeVisible();
    await expect(page.getByText(/서버에 연결하지 못했습니다/)).toHaveCount(0);
  });

  test("로그인 방식이 모두 꺼져 있으면 설정을 안내한다", async ({ page }) => {
    await page.route("**/api/v1/auth/config", (route) =>
      route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify({
          localEnabled: false,
          oidcEnabled: false,
          version: { name: "SeatOn", version: "test" },
        }),
      }),
    );
    await page.goto("/login");
    await expect(
      page.getByText(/사용 가능한 로그인 방식이 없습니다/),
    ).toBeVisible();
  });
});

test.describe("깊은 링크(returnTo)", () => {
  test("로그아웃 상태로 보호 경로를 열면 로그인 뒤 그 자리로 돌아간다", async ({
    page,
  }) => {
    // 링크로 공유받은 주소는 로그인 화면을 지나면서 사라지곤 했다. 로그인에
    // 성공해도 좌석맵 첫 화면으로 떨어지면 받은 링크는 쓸모가 없다.
    await page.goto("/admin/maps?floor=3");
    await page.waitForURL(
      (url) =>
        url.pathname === "/login" &&
        url.searchParams.get("returnTo") === "/admin/maps?floor=3",
    );
    await submitLoginForm(page);
    await page.waitForURL(
      (url) => url.pathname === "/admin/maps" && url.search === "?floor=3",
    );
    await expect(page.locator("main, [role=main]").first()).toBeVisible();
  });

  test("기본 경로에서 밀려난 로그인은 주소가 그대로 /login 이고 로그인 뒤 '/' 로 간다", async ({
    page,
  }) => {
    // 로그인 뒤 주소에 '/login' 이 남으면 helpers 의 login() 이 영원히 기다린다.
    await page.goto("/");
    await page.waitForURL((url) => url.pathname === "/login");
    expect(new URL(page.url()).search).toBe("");
    await submitLoginForm(page);
    await page.waitForURL((url) => url.pathname === "/");
  });

  test("SSO 단추도 깊은 링크를 들고 간다", async ({ page }) => {
    await page.route("**/api/v1/auth/config", (route) =>
      route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify({
          localEnabled: true,
          oidcEnabled: true,
          version: { name: "SeatOn", version: "test" },
        }),
      }),
    );
    await page.goto("/admin/maps");
    await page.waitForURL((url) => url.pathname === "/login");
    await expect(
      page.getByRole("link", { name: "사내 SSO로 로그인" }),
    ).toHaveAttribute(
      "href",
      "/api/v1/auth/oidc/start?returnTo=%2Fadmin%2Fmaps",
    );

    // returnTo 가 없으면 지금처럼 파라미터 없이 출발한다.
    await page.goto("/login");
    await expect(
      page.getByRole("link", { name: "사내 SSO로 로그인" }),
    ).toHaveAttribute("href", "/api/v1/auth/oidc/start");
  });
});

test.describe("조용한 SSO(prompt=none)", () => {
  // 서버의 auth/config 만 바꿔 auto_login 을 켠 것처럼 만들고, Keycloak 대신
  // 시작 경로를 가로채 "세션 없음"(login_required) 을 받은 콜백처럼
  // /login?sso=none 으로 돌려보낸다. 이 검증의 전부는 그 뒤에 다시 시도하지
  // 않는 것이다 — 다시 시도하면 브라우저가 제공자와 앱 사이를 끝없이 오간다.
  const autoLoginConfig = (page: Page, autoLogin: boolean) =>
    page.route("**/api/v1/auth/config", (route) =>
      route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify({
          localEnabled: true,
          oidcEnabled: true,
          oidcAutoLogin: autoLogin,
          version: { name: "SeatOn", version: "test" },
        }),
      }),
    );
  const refuseSilently = async (page: Page) => {
    const starts: string[] = [];
    await page.route("**/api/v1/auth/oidc/start*", (route) => {
      starts.push(route.request().url());
      return route.fulfill({
        status: 302,
        headers: { location: "/login?sso=none" },
      });
    });
    return starts;
  };

  test("세션이 없으면 한 번만 시도하고 거절 뒤에는 새로고침해도 다시 가지 않는다", async ({
    page,
  }) => {
    await autoLoginConfig(page, true);
    const starts = await refuseSilently(page);
    await page.goto("/admin/maps?floor=3");
    await page.waitForURL(/\/login\?sso=none$/);
    expect(starts).toHaveLength(1);
    const start = new URL(starts[0]);
    expect(start.searchParams.get("prompt")).toBe("none");
    // 깊은 링크로 들어온 자리를 들고 간다.
    expect(start.searchParams.get("returnTo")).toBe("/admin/maps?floor=3");
    await expect(page.locator('input[autocomplete="username"]')).toBeVisible();

    // 거절당한 뒤 새로고침 — 주소의 표시가 막는다.
    await page.reload();
    await expect(page.locator('input[autocomplete="username"]')).toBeVisible();
    expect(starts).toHaveLength(1);

    // 같은 탭에서 표시 없는 주소로 다시 들어와도 sessionStorage 가 막는다.
    await page.goto("/");
    await page.waitForURL(/\/login$/);
    await expect(page.locator('input[autocomplete="username"]')).toBeVisible();
    expect(starts).toHaveLength(1);
  });

  test("새 탭(새 세션 저장소)에서는 다시 한 번 시도한다", async ({ browser }) => {
    const context = await browser.newContext();
    const page = await context.newPage();
    await autoLoginConfig(page, true);
    const starts = await refuseSilently(page);
    await page.goto("/");
    await page.waitForURL(/\/login\?sso=none$/);
    expect(starts).toHaveLength(1);
    await context.close();
  });

  test("auto_login 이 꺼져 있으면 아무것도 달라지지 않는다", async ({ page }) => {
    await autoLoginConfig(page, false);
    const starts = await refuseSilently(page);
    await page.goto("/");
    await page.waitForURL(/\/login$/);
    await expect(page.locator('input[autocomplete="username"]')).toBeVisible();
    expect(starts).toHaveLength(0);
  });

  test("로그인 화면 자체에서는 시도하지 않는다", async ({ page }) => {
    await autoLoginConfig(page, true);
    const starts = await refuseSilently(page);
    await page.goto("/login");
    await expect(page.locator('input[autocomplete="username"]')).toBeVisible();
    expect(starts).toHaveLength(0);
  });
});
