describe(\"직원 필터 URL\", () => {
  it(\"빈 주소는 네 빈 문자열로 읽는다\", () => {
    expect(readEmployeeParams(new URLSearchParams())).toEqual({
      q: \"\", organizationId: \"\", status: \"\", assignment: \"\",
    });
  });

  it.each([\"active\", \"leave\", \"retired\"])(\"%s와 배정 조건이 URL/API를 왕복한다\", (status) => {
    for (const assignment of [\"assigned\", \"unassigned\"]) {
      const filters = { q: \"  김 & 개발 +  \", organizationId: \" org-1 \", status, assignment };
      const url = writeEmployeeParams(new URLSearchParams(\"other=keep&limit=1\"), filters);
      const read = readEmployeeParams(url);
      expect(read).toEqual({ ...filters, q: \"김 & 개발 +\", organizationId: \"org-1\" });
      expect(employeeQuery(read)).toEqual(employeeQuery(filters));
      expect(employeeQuery(read).get(\"limit\")).toBe(\"500\");
      expect(employeeQuery(read).has(\"other\")).toBe(false);
      expect(url.get(\"other\")).toBe(\"keep\");
    }
  });

  it(\"읽기는 공백을 제거하고 모르는 enum을 전체로 처리한다\", () => {
    const params = new URLSearchParams(\"q=+++&organizationId=+org-1+&status=ACTIVE&assignment=all\");
    const before = params.toString();
    expect(readEmployeeParams(params)).toEqual({ q: \"\", organizationId: \"org-1\", status: \"\", assignment: \"\" });
    expect(params.toString()).toBe(before);
  });

  it(\"쓰기의 빈 값과 알 수 없는 enum은 해당 키를 지운다\", () => {
    const original = new URLSearchParams(\"q=old&organizationId=org-1&status=active&assignment=assigned&other=a&other=b\");
    const before = original.toString();
    const next = writeEmployeeParams(original, { q: \"  \", organizationId: \"\", status: \"unknown\", assignment: \"all\" });
    expect(next.toString()).toBe(\"other=a&other=b\");
    expect(original.toString()).toBe(before);
  });

  it(\"undefined는 기존 조건을 보존하고 새 URLSearchParams를 반환한다\", () => {
    const original = new URLSearchParams(\"q=old&organizationId=org-1&status=active&assignment=assigned&other=keep\");
    const next = writeEmployeeParams(original, { q: \" new \", status: undefined });
    expect(readEmployeeParams(next)).toEqual({ q: \"new\", organizationId: \"org-1\", status: \"active\", assignment: \"assigned\" });
    expect(next.get(\"other\")).toBe(\"keep\");
    expect(original.get(\"q\")).toBe(\"old\");
    expect(writeEmployeeParams(original, {})).not.toBe(original);
  });

