    const filters = { status: \" active \", assignment: \" assigned \" };
    expect(readEmployeeParams(writeEmployeeParams(new URLSearchParams(), filters))).toEqual({ q: \"\", organizationId: \"\", status: \"active\", assignment: \"assigned\" });
    expect(employeeQuery(filters).toString()).toBe(\"limit=500&status=active&assignment=assigned\");
  });
});
