// 주소/컨트롤/API/표를 함께 검증한다. 응답은 실제 서버와 DB에서 받는다.
test.describe(\"직원 필터 URL\", () => {
  test.beforeEach(async ({ page }) => login(page));

  const organizations = async (page: import(\"@playwright/test\").Page) => {
    const response = await page.request.get(\"/api/v1/organizations\");
    expect(response.ok()).toBe(true);
    return (await response.json()).items as import(\"../src/types\").Organization[];
  };
  const isList = (url: string) => new URL(url).pathname === \"/api/v1/employees\";
  const choose = async (page: import(\"@playwright/test\").Page, label: string, name: string) => {
    await page.getByRole(\"combobox\", { name: label }).click();
    await page.getByRole(\"option\", { name, exact: true }).click();
  };

  test(\"직접 진입과 새로고침이 네 필터·실제 조회·CSV를 복원한다\", async ({ page }) => {
    const orgs = await organizations(page);
    const sales = orgs.find((org) => org.name === \"영업팀\")"'!.id;
    const params = new URLSearchParams({ q: " 영업팀 ", organizationId: sales, status: "active", assignment: "assigned", other: "keep", limit: "1" });
    const requests: URL[] = [];
    page.on("request", (request) => { if (isList(request.url())) requests.push(new URL(request.url())); });
    await page.goto(`/admin/employees?${params}`);
    for (let visit = 0; visit < 2; visit++) {
      if (visit) await page.reload();
      await expect(page.getByPlaceholder("이름, 사번, 이메일, 조직 검색")).toHaveValue("영업팀");
      await expect(page.getByRole("combobox", { name: "조직 필터" })).toHaveText("영업팀");
      await expect(page.getByRole("combobox", { name: "재직상태 필터" })).toHaveText("재직");
      await expect(page.getByRole("combobox", { name: "배정상태 필터" })).toHaveText("배정");
      await expect(page.locator("table tbody tr")).toHaveCount(2);
      expect(await page.locator("table tbody tr td:nth-child(3)").allTextContents()).toEqual(["영업팀", "영업팀"]);
      expect(requests).toHaveLength(visit + 1);
      expect(Object.fromEntries(requests.at(-1)!.searchParams)).toEqual({ limit: "500", q: "영업팀", organizationId: sales, status: "active", assignment: "assigned" });
    }
    const wait = page.waitForEvent("download");
    await page.getByRole("button", { name: "CSV 내보내기" }).click();
    const csv = readFileSync((await (await wait).path())!, "utf8");
    expect(csv.split("'"\\r\\n\")).toHaveLength(3);
    expect(csv).toContain(\"영업팀\");
    expect(csv).not.toContain(\"개발팀\");
  });

  test(\"제출·Select는 replace로 조건을 보존하고 빈 값은 지우며 같은 검색도 다시 조회한다\", async ({ page }) => {
    const dev = (await organizations(page)).find((org) => org.name === \"개발팀\")"'!.id;
    await page.goto("/admin/employees?other=keep");
    await expect(page.locator("table tbody tr")).toHaveCount(10);
    const historyLength = await page.evaluate(() => history.length);
    const requests: string[] = [];
    page.on("request", (request) => { if (isList(request.url())) requests.push(request.url()); });
    const search = page.getByPlaceholder("이름, 사번, 이메일, 조직 검색");
    await search.fill("  김개발  ");
